Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
fbdev: vt8500lcdfb: fix missing dma_free_coherent()

fbi->fb.screen_buffer is allocated with dma_alloc_coherent() but is not
freed if the error path is reached.

Fixes: e7b995371fe1 ("video: vt8500: Add devicetree support for vt8500-fb and wm8505-fb")
Cc: <stable@vger.kernel.org>
Signed-off-by: Thomas Fourier <fourier.thomas@gmail.com>
Signed-off-by: Helge Deller <deller@gmx.de>

Here is the root cause:
In vt8500lcd_probe, when palette allocation fails, the error path jumps to 'failed_free_io', which only unmaps I/O memory but does not free the DMA-coherent screen buffer (fbi->fb.screen_buffer) that was allocated earlier. This causes a memory leak.

Here is the patch:

 static int vt8500lcd_probe(struct platform_device *pdev)
 {
 	struct vt8500lcd_info *fbi;
 	struct resource *res;
 	struct display_timings *disp_timing;
 	void *addr;
 	int irq, ret;

 	struct fb_videomode	of_mode;
 	u32			bpp;
 	dma_addr_t fb_mem_phys;
 	unsigned long fb_mem_len;
 	void *fb_mem_virt;

 	ret = -ENOMEM;
 	fbi = NULL;

 	fbi = devm_kzalloc(&pdev->dev, sizeof(struct vt8500lcd_info)
 			+ sizeof(u32) * 16, GFP_KERNEL);
 	if (!fbi)
 		return -ENOMEM;

 	strcpy(fbi->fb.fix.id, "VT8500 LCD");

 	fbi->fb.fix.type	= FB_TYPE_PACKED_PIXELS;
 	fbi->fb.fix.xpanstep	= 0;
 	fbi->fb.fix.ypanstep	= 1;
 	fbi->fb.fix.ywrapstep	= 0;
 	fbi->fb.fix.accel	= FB_ACCEL_NONE;

 	fbi->fb.var.nonstd	= 0;
 	fbi->fb.var.activate	= FB_ACTIVATE_NOW;
 	fbi->fb.var.height	= -1;
 	fbi->fb.var.width	= -1;
 	fbi->fb.var.vmode	= FB_VMODE_NONINTERLACED;

 	fbi->fb.fbops		= &vt8500lcd_ops;
 	fbi->fb.flags		= FBINFO_HWACCEL_COPYAREA
 				| FBINFO_HWACCEL_FILLRECT
 				| FBINFO_HWACCEL_YPAN
 				| FBINFO_VIRTFB
 				| FBINFO_PARTIAL_PAN_OK;
 	fbi->fb.node		= -1;

 	addr = fbi;
 	addr = addr + sizeof(struct vt8500lcd_info);
 	fbi->fb.pseudo_palette	= addr;

 	res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
 	if (res == NULL) {
 		dev_err(&pdev->dev, "no I/O memory resource defined\n");
 		return -ENODEV;
 	}

 	res = request_mem_region(res->start, resource_size(res), "vt8500lcd");
 	if (res == NULL) {
 		dev_err(&pdev->dev, "failed to request I/O memory\n");
 		return -EBUSY;
 	}

 	fbi->regbase = ioremap(res->start, resource_size(res));
 	if (fbi->regbase == NULL) {
 		dev_err(&pdev->dev, "failed to map I/O memory\n");
 		ret = -EBUSY;
 		goto failed_free_res;
 	}

 	disp_timing = of_get_display_timings(pdev->dev.of_node);
 	if (!disp_timing) {
 		ret = -EINVAL;
 		goto failed_free_io;
 	}

 	ret = of_get_fb_videomode(pdev->dev.of_node, &of_mode,
 							OF_USE_NATIVE_MODE);
 	if (ret)
 		goto failed_free_io;

 	ret = of_property_read_u32(pdev->dev.of_node, "bits-per-pixel", &bpp);
 	if (ret)
 		goto failed_free_io;

 	/* try allocating the framebuffer */
 	fb_mem_len = of_mode.xres * of_mode.yres * 2 * (bpp / 8);
 	fb_mem_virt = dma_alloc_coherent(&pdev->dev, fb_mem_len, &fb_mem_phys,
 				GFP_KERNEL);
 	if (!fb_mem_virt) {
 		pr_err("%s: Failed to allocate framebuffer\n", __func__);
 		ret = -ENOMEM;
 		goto failed_free_io;
 	}

 	fbi->fb.fix.smem_start	= fb_mem_phys;
 	fbi->fb.fix.smem_len	= fb_mem_len;
 	fbi->fb.screen_buffer	= fb_mem_virt;

 	fbi->palette_size	= PAGE_ALIGN(512);
 	fbi->palette_cpu	= dma_alloc_coherent(&pdev->dev,
 						     fbi->palette_size,
 						     &fbi->palette_phys,
 						     GFP_KERNEL);
 	if (fbi->palette_cpu == NULL) {
 		dev_err(&pdev->dev, "Failed to allocate palette buffer\n");
 		ret = -ENOMEM;
-		goto failed_free_io;
+		goto failed_free_mem_virt;
 	}

 	irq = platform_get_irq(pdev, 0);
 	if (irq < 0) {
 		ret = -ENODEV;
 		goto failed_free_palette;
 	}

 	ret = request_irq(irq, vt8500lcd_handle_irq, 0, "LCD", fbi);
 	if (ret) {
 		dev_err(&pdev->dev, "request_irq failed: %d\n", ret);
 		ret = -EBUSY;
 		goto failed_free_palette;
 	}

 	init_waitqueue_head(&fbi->wait);

 	if (fb_alloc_cmap(&fbi->fb.cmap, 256, 0) < 0) {
 		dev_err(&pdev->dev, "Failed to allocate color map\n");
 		ret = -ENOMEM;
 		goto failed_free_irq;
 	}

 	fb_videomode_to_var(&fbi->fb.var, &of_mode);

 	fbi->fb.var.xres_virtual	= of_mode.xres;
 	fbi->fb.var.yres_virtual	= of_mode.yres * 2;
 	fbi->fb.var.bits_per_pixel	= bpp;

 	ret = vt8500lcd_set_par(&fbi->fb);
 	if (ret) {
 		dev_err(&pdev->dev, "Failed to set parameters\n");
 		goto failed_free_cmap;
 	}

 	writel(fbi->fb.fix.smem_start >> 22, fbi->regbase + 0x1c);
 	writel((fbi->palette_phys & 0xfffffe00) | 1, fbi->regbase + 0x18);

 	platform_set_drvdata(pdev, fbi);

 	ret = register_framebuffer(&fbi->fb);
 	if (ret < 0) {
 		dev_err(&pdev->dev,
 			"Failed to register framebuffer device: %d\n", ret);
 		goto failed_free_cmap;
 	}

 	/*
 	 * Ok, now enable the LCD controller
 	 */
 	writel(readl(fbi->regbase) | 1, fbi->regbase);

 	return 0;

 failed_free_cmap:
 	if (fbi->fb.cmap.len)
 		fb_dealloc_cmap(&fbi->fb.cmap);
 failed_free_irq:
 	free_irq(irq, fbi);
 failed_free_palette:
 	dma_free_coherent(&pdev->dev, fbi->palette_size,
 			  fbi->palette_cpu, fbi->palette_phys);
+failed_free_mem_virt:
+	dma_free_coherent(&pdev->dev, fbi->fb.fix.smem_len,
+			  fbi->fb.screen_buffer, fbi->fb.fix.smem_start);
 failed_free_io:
 	iounmap(fbi->regbase);
 failed_free_res:
 	release_mem_region(res->start, resource_size(res));
 	return ret;
 }



